class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._static_routes = []
        self._dynamic_routes = []

    def add(self, path, handler):
        if '<' in path:
            self._dynamic_routes.append((path, handler))
        else:
            self._static_routes.append((path, handler))

    def _parse_dynamic(self, pattern, path):
        """Try to match a dynamic pattern against a path.

        Returns (True, params) if it matches, (False, {}) otherwise.
        """
        pattern_segments = pattern.split('/')
        path_segments = path.split('/')

        if len(pattern_segments) != len(path_segments):
            return False, {}

        params = {}
        for p_seg, path_seg in zip(pattern_segments, path_segments):
            if p_seg.startswith('<') and p_seg.endswith('>'):
                param_name = p_seg[1:-1]
                if not path_seg:
                    return False, {}
                params[param_name] = path_seg
            else:
                if p_seg != path_seg:
                    return False, {}

        return True, params

    def resolve(self, path):
        # Static routes always win over dynamic routes
        for route, handler in self._static_routes:
            if route == path:
                return handler, {}

        # Then check dynamic routes in registration order
        for route, handler in self._dynamic_routes:
            matches, params = self._parse_dynamic(route, path)
            if matches:
                return handler, params

        return None, {}

