"""Router supporting static and parameterized path segments.

Routes are registered with `add`, and `resolve` returns (handler, params)
for a matching path or (None, {}) when nothing matches.
"""


class Router:

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # First pass: try all static routes (no <...> segments)
        for route, handler in self._routes:
            if "<" not in route:
                if route == path:
                    return handler, {}

        # Second pass: try all dynamic routes (has <...> segments)
        for route, handler in self._routes:
            if "<" in route:
                route_segments = route.split("/")
                path_segments = path.split("/")
                if len(route_segments) != len(path_segments):
                    continue
                params = {}
                match = True
                for rs, ps in zip(route_segments, path_segments):
                    if rs.startswith("<") and rs.endswith(">"):
                        # Parameter segment – must be non-empty
                        if not ps:
                            match = False
                            break
                        params[rs[1:-1]] = ps
                    elif rs != ps:
                        match = False
                        break
                if match:
                    return handler, params

        return None, {}
